    title text NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    category text DEFAULT 'studio'::text NOT NULL,
    venue_type text DEFAULT 'studio'::text NOT NULL,
    address text DEFAULT ''::text NOT NULL,
    city text DEFAULT ''::text NOT NULL,
    region text,
    country text,
    postal_code text,
    latitude numeric(20,8) DEFAULT 0 NOT NULL,
    longitude numeric(20,8) DEFAULT 0 NOT NULL,
    capacity integer DEFAULT 0 NOT NULL,
    square_feet numeric(20,4),
    hourly_rate numeric(20,4),
    hourly_rate_cents integer,
    daily_rate_cents integer,
    currency text DEFAULT 'USD'::text NOT NULL,
    photos jsonb DEFAULT '[]'::jsonb NOT NULL,
    amenities jsonb DEFAULT '[]'::jsonb NOT NULL,
    house_rules text,
    rating numeric(20,4) DEFAULT 0 NOT NULL,
    reviews_count integer DEFAULT 0 NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone,
    "updatedAt" timestamp with time zone
);


